   const provider=select(t('Read source','Okunacak kaynak'),[['anilist','AniList'],['mal','MAL XML']],mode==='read'?'anilist':'mal'),pool=select(t('Source pool','Kaynak havuzu'),[['anime',name('anime')],['manga',name('manga')]],['anime','manga'].includes(domain)?domain:'anime'),username=el('input','plog-search');username.setAttribute('aria-label',t('Public AniList username','Herkese açık AniList kullanıcı adı'));username.placeholder=t('AniList username','AniList kullanıcı adı');if(mode==='read')d.append(provider.label,pool.label,username,el('p','plog-explainer',t('AniList reads the chosen public list only when requested. MAL uses a fresh XML export pasted below; no MAL account API connection is configured. Nothing is sent back to either service. Missing remote titles never delete local records.','AniList seçilen açık listeyi yalnız isteğinle okur. MAL için yeni XML dışa aktarımını aşağıya yapıştır; MAL hesap API bağlantısı yapılandırılmadı. İki servise de geri yazılmaz. Kaynakta eksilen yapımlar yerel kayıtları silmez.')));
