   input.oninput=username.oninput=provider.input.onchange=pool.input.onchange=()=>{token=null;decisions=[];preview.replaceChildren();message.textContent='';save.textContent=t('Preview import','İçe aktarımı incele');input.hidden=mode==='read'&&provider.input.value==='anilist';username.hidden=mode!=='read'||provider.input.value!=='anilist';pool.label.hidden=mode!=='read'||provider.input.value!=='anilist';};input.hidden=mode==='read';username.hidden=mode!=='read';if(mode==='read')d.querySelector('h2').textContent=t('Read list · review changes','Listeyi oku · farkları incele');d.append(save,preview,button(t('Cancel','Vazgeç'),()=>d.close()));d.showModal();input.focus();
